<h1>Application Settings</h1><?php if(isset($_GET['saved'])):?><p class="ok">Branding settings saved.</p><?php endif?><form method="post" enctype="multipart/form-data" class="settings-page"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><section class="card"><h2>Identity and header</h2><label>Application name<input name="app_name" value="<?=e($branding['app_name']??app_name())?>" required></label><label>Header mode<select name="header_mode"><option value="text" <?=($branding['header_mode']??'text')==='text'?'selected':''?>>Text</option><option value="image" <?=($branding['header_mode']??'')==='image'?'selected':''?>>Full-width image</option></select></label><label>Header title<input name="header_title" value="<?=e($branding['header_title']??app_name())?>"></label><label>Header subtitle<input name="header_subtitle" value="<?=e($branding['header_subtitle']??'Sistem Antrean Digital')?>"></label><label>Existing image URL/path<input name="header_image_url" value="<?=e($branding['header_image_url']??'')?>"></label><label>Upload header image<input type="file" name="header_image" accept="image/png,image/jpeg,image/webp"></label></section><section class="card"><h2>Theme and running text</h2><label>Primary color<input type="color" name="primary_color" value="<?=e($branding['primary_color']??'#075f91')?>"></label><label>Secondary color<input type="color" name="secondary_color" value="<?=e($branding['secondary_color']??'#1478c8')?>"></label><label>Accent color<input type="color" name="accent_color" value="<?=e($branding['accent_color']??'#ffd94f')?>"></label><label>Running footer text<textarea name="footer_text" rows="4" maxlength="300" required><?=e($branding['footer_text']??'Mohon menunggu nomor antrean Anda dipanggil')?></textarea></label><button type="submit">Save all settings</button></section></form>
<form id="header-height-settings" class="card header-height-settings"><h2>Header Height</h2><div><label>Height mode<select name="mode"><option value="fixed" <?=($branding['header_height_mode']??'fixed')==='fixed'?'selected':''?>>Compact fixed height</option><option value="auto" <?=($branding['header_height_mode']??'')==='auto'?'selected':''?>>Automatic from image ratio</option></select></label><label>Fixed height (60–300 px)<input type="number" name="height" min="60" max="300" value="<?=e($branding['header_height_px']??'100')?>"></label><button type="submit">Apply header height</button></div><p id="header-height-status">Compact mode is recommended for operator and kiosk screens.</p></form>
<form id="admin-display-settings" class="card admin-media-settings" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><h2>Display Media</h2><div class="settings-page"><section><label>Media source<select name="media_type"><option value="none" <?=($branding['display_media_type']??'none')==='none'?'selected':''?>>No media</option><option value="local" <?=($branding['display_media_type']??'')==='local'?'selected':''?>>Single local video</option><option value="playlist" <?=($branding['display_media_type']??'')==='playlist'?'selected':''?>>Local folder playlist</option><option value="youtube" <?=($branding['display_media_type']??'')==='youtube'?'selected':''?>>YouTube</option><option value="obs" <?=($branding['display_media_type']??'')==='obs'?'selected':''?>>OBS / stream URL</option></select></label><label>Media URL or local path<input name="media_url" value="<?=e($branding['display_media_url']??'')?>"></label><label>Upload single local video<input type="file" name="media_file" accept="video/mp4,video/webm,video/ogg"></label><label class="media-check"><input type="checkbox" name="media_muted" <?=($branding['display_media_muted']??'1')==='1'?'checked':''?>> Mute media</label></section><section><label>Add videos to playlist<input type="file" name="playlist_files[]" accept="video/mp4,video/webm,video/ogg" multiple></label><label class="media-check"><input type="checkbox" name="clear_playlist"> Clear existing playlist before upload</label><div class="playlist-files"><b>Current playlist (<?=count($playlistFiles)?>)</b><?php if($playlistFiles):?><ol><?php foreach($playlistFiles as $file):?><li><?=e($file)?></li><?php endforeach?></ol><?php else:?><p>No local playlist videos uploaded.</p><?php endif?></div></section></div><button type="submit">Save display media</button><p id="admin-media-status">Playlist plays all MP4, WebM, and OGG files in filename order.</p></form><script>window.ADMIN_CSRF=<?=json_encode(csrf_token())?>;</script><script src="/assets/admin-settings.js"></script>
